"""Create the stage report with Pandoc OMML and deterministic OOXML styling."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
import xml.etree.ElementTree as E
import subprocess, json, re

ROOT=Path(__file__).resolve().parents[2]
TMP=Path(__file__).resolve().parent
SRC=ROOT/'docs/4.4/vs_4.3/experiments/reports/2026-10-24_STAGE_EXPERIMENT_REPORT.md'
OUT=SRC.with_suffix('.docx')
NS={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main',
    'm':'http://schemas.openxmlformats.org/officeDocument/2006/math',
    'r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'wp':'http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing',
    'a':'http://schemas.openxmlformats.org/drawingml/2006/main'}
for prefix,uri in NS.items(): E.register_namespace(prefix,uri)
def tag(s):
    a,b=s.split(':'); return '{'+NS[a]+'}'+b
def sub(parent,s,**attrs):
    node=E.SubElement(parent,tag(s));
    for k,v in attrs.items(): node.set(tag('w:'+k),str(v))
    return node
def get(parent,s):
    node=parent.find(tag(s)); return node if node is not None else sub(parent,s)
def fonts(rpr, size=24, bold=False):
    rf=get(rpr,'w:rFonts'); rf.attrib.clear()
    for a,v in [('ascii','Times New Roman'),('hAnsi','Times New Roman'),('eastAsia','SimSun'),('cs','Times New Roman')]:rf.set(tag('w:'+a),v)
    for s in ['w:sz','w:szCs']:get(rpr,s).set(tag('w:val'),str(size))
    color=get(rpr,'w:color');color.attrib.clear();color.set(tag('w:val'),'000000')
    if bold:get(rpr,'w:b')
def prop(p,name,**attrs):
    el=get(get(p,'w:pPr'),name)
    for k,v in attrs.items():el.set(tag('w:'+k),str(v))
    return el
def serialize(tree):
    for n in tree.iter():
        n.attrib.pop('{http://schemas.openxmlformats.org/markup-compatibility/2006}Ignorable',None)
    return E.tostring(tree,encoding='utf-8',xml_declaration=True)

text=SRC.read_text(encoding='utf-8-sig')
title=text.splitlines()[0].lstrip('# ')
body='\n'.join(text.splitlines()[1:])
# Human-facing source links stay relative in Markdown; Word uses local absolute targets.
def abs_link(match):
    target=match.group(2)
    if target.startswith(('https:','http:','#')) or match.group(1).startswith('!'):return match.group(0)
    path,sep,anchor=target.partition('#')
    return match.group(1)+'('+str((SRC.parent/path).resolve()).replace('\\','/')+(sep+anchor if sep else '')+')'
body=re.sub(r'(!?\[[^\]\n]*\])\(([^)\n]+)\)',abs_link,body)
buildmd=TMP/'word_source.md';buildmd.write_text(body,encoding='utf-8')
raw=TMP/'pandoc_raw.docx'
args=['C:/Program Files/Pandoc/pandoc.exe',str(buildmd),'-f','markdown+tex_math_dollars-implicit_figures',
      '-t','docx','--standalone','--shift-heading-level-by=-1',
      '--metadata','title='+title,'--resource-path='+str(SRC.parent),'-o',str(raw)]
proc=subprocess.run(args,capture_output=True,text=True,encoding='utf-8')
(TMP/'pandoc.log').write_text(proc.stdout+proc.stderr,encoding='utf-8')
if proc.returncode or 'Could not convert TeX math' in proc.stderr:raise RuntimeError(proc.stderr)
with ZipFile(raw) as z:files={n:z.read(n) for n in z.namelist()}
styles=E.fromstring(files['word/styles.xml'])
defaults=get(styles,'w:docDefaults');fonts(get(get(defaults,'w:rPrDefault'),'w:rPr'))
for st in styles.findall('w:style',NS):
    sid=st.get(tag('w:styleId'),'')
    if st.get(tag('w:type')) not in ('paragraph','character'):continue
    rp=get(st,'w:rPr'); fonts(rp)
    if st.get(tag('w:type'))=='paragraph':
        pp=get(st,'w:pPr');get(pp,'w:spacing').attrib.update({tag('w:after'):'100',tag('w:line'):'300',tag('w:lineRule'):'auto'})
        get(pp,'w:ind').set(tag('w:firstLine'),'480')
        get(pp,'w:widowControl')
    if sid in ('Heading1','Heading2','Heading3','Title','Subtitle'):
        fonts(rp,{'Title':36,'Heading1':30,'Heading2':26,'Heading3':24,'Subtitle':24}[sid],True)
        pp=get(st,'w:pPr'); get(pp,'w:ind').set(tag('w:firstLine'),'0');get(pp,'w:keepNext');get(pp,'w:keepLines')
        get(pp,'w:spacing').attrib.update({tag('w:before'):'200',tag('w:after'):'100'})
    if sid in ('Caption','ImageCaption','TableCaption'):
        fonts(rp,21);get(get(st,'w:pPr'),'w:ind').set(tag('w:firstLine'),'0')
        get(get(st,'w:pPr'),'w:spacing').set(tag('w:line'),'260')
    if sid in ('VerbatimChar','SourceCode'):fonts(rp,20)
files['word/styles.xml']=serialize(styles)
doc=E.fromstring(files['word/document.xml']); b=doc.find('w:body',NS)
for p in b.findall('w:p',NS):
    tx=''.join(p.itertext())
    if p.find('.//m:oMathPara',NS) is not None:
        prop(p,'w:ind',firstLine=0);prop(p,'w:jc',val='center');prop(p,'w:keepLines')
    if p.find('.//w:drawing',NS) is not None:
        prop(p,'w:ind',firstLine=0);prop(p,'w:jc',val='center');prop(p,'w:keepNext');prop(p,'w:keepLines')
        # Scale large raster figures to content width while preserving aspect ratio.
        for extent in p.findall('.//wp:extent',NS):
            cx,cy=int(extent.get('cx')),int(extent.get('cy'));maxcx=5651500
            scale=min(1,maxcx/cx,5905500/cy)
            new=(int(cx*scale),int(cy*scale));extent.set('cx',str(new[0]));extent.set('cy',str(new[1]))
            for ext in p.findall('.//a:xfrm/a:ext',NS):ext.set('cx',str(new[0]));ext.set('cy',str(new[1]))
    if re.match(r'^图[1-4] ',tx):
        prop(p,'w:ind',firstLine=0);prop(p,'w:spacing',line=260,after=120);prop(p,'w:keepLines')
        for r in p.findall('w:r',NS):fonts(get(r,'w:rPr'),21)
children=list(b)
for idx,node in enumerate(children[:-1]):
    nxt=children[idx+1]
    if node.tag==tag('w:p') and nxt.find('.//m:oMathPara',NS) is not None:
        prop(node,'w:keepNext')
for table in doc.findall('.//w:tbl',NS):
    pr=get(table,'w:tblPr');get(pr,'w:tblLayout').set(tag('w:type'),'fixed')
    get(pr,'w:tblW').attrib.update({tag('w:w'):'9360',tag('w:type'):'dxa'})
    rows=table.findall('w:tr',NS);cols=len(rows[0].findall('w:tc',NS))
    head=''.join(rows[0].itertext())
    if '尺度口径' in ''.join(table.itertext()):ratios=[.17,.25,.29,.29]
    elif '支持内容' in head:ratios=[.21,.32,.47]
    elif '数学含义' in head:ratios=[.19,.43,.38]
    elif cols==3:ratios=[.23,.43,.34]
    elif cols==4:ratios=[.24,.25,.26,.25]
    else:ratios=[1/cols]*cols
    widths=[int(9360*x) for x in ratios]
    grid=get(table,'w:tblGrid');grid.clear()
    for width in widths:sub(grid,'w:gridCol',w=width)
    for ri,row in enumerate(rows):
        trp=get(row,'w:trPr');get(trp,'w:cantSplit')
        if ri==0:get(trp,'w:tblHeader')
        for ci,cell in enumerate(row.findall('w:tc',NS)):
            cp=get(cell,'w:tcPr');get(cp,'w:tcW').attrib.update({tag('w:w'):str(widths[ci]),tag('w:type'):'dxa'})
            mar=get(cp,'w:tcMar')
            for side in ['top','bottom','left','right']:get(mar,'w:'+side).attrib.update({tag('w:w'):'150' if side in ('left','right') else '70',tag('w:type'):'dxa'})
            if ri==0:get(cp,'w:shd').set(tag('w:fill'),'EDEFF2')
            for p in cell.findall('w:p',NS):
                prop(p,'w:ind',firstLine=0);prop(p,'w:spacing',before=0,after=35,line=260);prop(p,'w:keepLines')
                if ci==0 and '工况' in head:prop(p,'w:jc',val='left')
                # All report tables fit on one A4 page. Keep adjacent rows together.
                if ri < len(rows)-1:prop(p,'w:keepNext')
                for r in p.findall('.//w:r',NS):fonts(get(r,'w:rPr'),21,ri==0)
for sect in doc.findall('.//w:sectPr',NS):
    get(sect,'w:pgSz').attrib.update({tag('w:w'):'11906',tag('w:h'):'16838'})
    get(sect,'w:pgMar').attrib.update({tag('w:top'):'1134',tag('w:bottom'):'1134',tag('w:left'):'1273',tag('w:right'):'1273',tag('w:header'):'567',tag('w:footer'):'567',tag('w:gutter'):'0'})
    sub(sect,'w:footerReference',type='default').set(tag('r:id'),'rIdStageFooter')
footer=E.Element(tag('w:ftr'));p=sub(footer,'w:p');prop(p,'w:jc',val='center');prop(p,'w:ind',firstLine=0)
fld=sub(p,'w:fldSimple',instr='PAGE');rr=sub(fld,'w:r');fonts(sub(rr,'w:rPr'),20);sub(rr,'w:t').text='1'
files['word/footer_stage.xml']=serialize(footer)
rels=E.fromstring(files['word/_rels/document.xml.rels']);relNS='http://schemas.openxmlformats.org/package/2006/relationships'
E.SubElement(rels,'{'+relNS+'}Relationship',{'Id':'rIdStageFooter','Type':NS['r']+'/footer','Target':'footer_stage.xml'})
files['word/_rels/document.xml.rels']=serialize(rels)
ct=E.fromstring(files['[Content_Types].xml']);E.SubElement(ct,'{http://schemas.openxmlformats.org/package/2006/content-types}Override',{'PartName':'/word/footer_stage.xml','ContentType':'application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml'})
files['[Content_Types].xml']=serialize(ct)
files['word/document.xml']=serialize(doc)
with ZipFile(OUT,'w',ZIP_DEFLATED) as z:
    for n,data in files.items():z.writestr(n,data)
result=dict(output=str(OUT),display_math=len(doc.findall('.//m:oMathPara',NS)),
            all_math=len(doc.findall('.//m:oMath',NS)),images=len(doc.findall('.//w:drawing',NS)),
            tables=len(doc.findall('.//w:tbl',NS)),pandoc_warnings=proc.stderr)
(TMP/'build_result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(result,ensure_ascii=False))
